import { ark, type HTMLArkProps } from '@ark-ui/solid/factory';
import type {
  ChartRenderer,
  ChartRendererHostOptions,
  ChartTooltipBodyContext,
  ChartTooltipBodyTarget,
  ChartValue,
} from '@tanstack/charts';
import { createChartRendererAdapter } from '@tanstack/charts/adapter/renderer';
import { motion as createMotionRenderer } from '@tanstack/charts/motion';
import { svgChartRenderer } from '@tanstack/charts/svg/renderer';
import { clsx } from 'clsx';
import {
  For,
  Show,
  createEffect,
  createMemo,
  createSignal,
  createUniqueId,
  onCleanup,
  onMount,
  splitProps,
  type Accessor,
  type JSX,
} from 'solid-js';
import { Portal } from 'solid-js/web';
import styles from './Chart.module.css';

const defaultChartRenderer = createMotionRenderer<unknown, ChartValue, ChartValue>({
  transition: {
    type: 'spring',
    stiffness: 260,
    damping: 30,
    mass: 0.8,
  },
});

type ChartTooltipContent = ChartTooltipBodyContext['content'];
type ChartTooltipObjectContent = Exclude<ChartTooltipContent, string>;

type ChartTooltipBodyRenderContext<
  TDatum = unknown,
  TXValue extends ChartValue = ChartValue,
  TYValue extends ChartValue = ChartValue,
> = ChartTooltipBodyContext<TDatum, TXValue, TYValue> & {
  defaultBody: JSX.Element;
};

type ChartTooltipBodyRenderProps<
  TDatum = unknown,
  TXValue extends ChartValue = ChartValue,
  TYValue extends ChartValue = ChartValue,
> = {
  renderTooltipBody?: (
    context: ChartTooltipBodyRenderContext<TDatum, TXValue, TYValue>,
  ) => JSX.Element;
};

type ChartPlotProps<
  TDatum,
  TXValue extends ChartValue = ChartValue,
  TYValue extends ChartValue = ChartValue,
> = Omit<ChartRendererHostOptions<TDatum, TXValue, TYValue>, 'onTooltipBodyChange' | 'renderer'> &
  ChartTooltipBodyRenderProps<TDatum, TXValue, TYValue> & {
    class?: string;
    style?: JSX.CSSProperties;
    motion?: boolean;
    renderer?: ChartRenderer<NoInfer<TDatum>, NoInfer<TXValue>, NoInfer<TYValue>>;
  };

function ChartRoot(props: HTMLArkProps<'figure'>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <ark.figure
      asChild={local.asChild}
      {...others}
      data-scope="chart"
      data-part="root"
      data-slot="chart-root"
      class={clsx(styles.root, local.class)}
    />
  );
}

function ModuixTooltipObjectContent(props: { content: Accessor<ChartTooltipObjectContent> }) {
  return (
    <div data-slot="chart-tooltip-body" class={styles.defaultTooltipContent}>
      <Show when={props.content().title}>
        <div data-slot="chart-tooltip-title" class={styles.tooltipTitle}>
          <Show when={props.content().color}>
            <span
              aria-hidden="true"
              data-slot="chart-tooltip-swatch"
              class={styles.tooltipSwatch}
              style={{ 'background-color': props.content().color }}
            />
          </Show>
          {props.content().title}
        </div>
      </Show>
      <Show when={props.content().rows.length}>
        <div data-slot="chart-tooltip-rows" class={styles.tooltipRows}>
          <For each={props.content().rows}>
            {(row) => (
              <div
                data-has-swatch={row.color ? '' : undefined}
                data-slot="chart-tooltip-row"
                class={styles.tooltipRow}
              >
                <Show when={row.color}>
                  <span
                    aria-hidden="true"
                    data-slot="chart-tooltip-swatch"
                    class={styles.tooltipSwatch}
                    style={{ 'background-color': row.color }}
                  />
                </Show>
                <span data-slot="chart-tooltip-label" class={styles.tooltipLabel}>
                  {row.label}
                </span>
                <span data-slot="chart-tooltip-value" class={styles.tooltipValue}>
                  {row.value}
                </span>
              </div>
            )}
          </For>
        </div>
      </Show>
    </div>
  );
}

function ModuixTooltipBody(props: { content: Accessor<ChartTooltipContent> }) {
  return (
    <>
      <Show when={typeof props.content() === 'string'}>
        <span data-slot="chart-tooltip-text">{props.content() as string}</span>
      </Show>
      <Show when={typeof props.content() !== 'string'}>
        <ModuixTooltipObjectContent content={() => props.content() as ChartTooltipObjectContent} />
      </Show>
    </>
  );
}

function TanStackTooltipSwatch(props: { color: string }) {
  return (
    <span
      aria-hidden="true"
      class="ts-chart-tooltip__swatch"
      style={{
        display: 'block',
        width: '0.55rem',
        height: '0.55rem',
        'border-radius': '0.15rem',
        'box-shadow': 'inset 0 0 0 1px rgb(0 0 0/.12)',
        background: props.color,
      }}
    />
  );
}

function TanStackTooltipObjectContent(props: { content: Accessor<ChartTooltipObjectContent> }) {
  return (
    <>
      <Show when={props.content().title}>
        <div
          class="ts-chart-tooltip__title"
          style={{
            display: 'flex',
            'align-items': 'center',
            gap: '0.4rem',
            'font-weight': 650,
            'margin-bottom': props.content().rows.length ? '0.3rem' : 0,
          }}
        >
          <Show when={props.content().color}>
            <TanStackTooltipSwatch color={props.content().color!} />
          </Show>
          {props.content().title}
        </div>
      </Show>
      <Show when={props.content().rows.length}>
        <div class="ts-chart-tooltip__rows" aria-hidden="true">
          <For each={props.content().rows}>
            {(row) => (
              <div
                class="ts-chart-tooltip__row"
                style={{
                  display: 'grid',
                  'grid-template-columns': '0.55rem minmax(0,1fr) auto',
                  'align-items': 'center',
                  'column-gap': '0.4rem',
                }}
              >
                {row.color ? <TanStackTooltipSwatch color={row.color} /> : <span />}
                <span>{row.label}</span>
                <span
                  style={{
                    'text-align': 'right',
                    'font-variant-numeric': 'tabular-nums',
                    'white-space': 'nowrap',
                  }}
                >
                  {row.value}
                </span>
              </div>
            )}
          </For>
        </div>
      </Show>
    </>
  );
}

function TanStackTooltipBody(props: { content: Accessor<ChartTooltipContent> }) {
  return (
    <>
      <Show when={typeof props.content() === 'string'}>{props.content() as string}</Show>
      <Show when={typeof props.content() !== 'string'}>
        <TanStackTooltipObjectContent
          content={() => props.content() as ChartTooltipObjectContent}
        />
      </Show>
    </>
  );
}

function ChartTooltipBody<TDatum, TXValue extends ChartValue, TYValue extends ChartValue>(props: {
  render: (context: ChartTooltipBodyRenderContext<TDatum, TXValue, TYValue>) => JSX.Element;
  target: Accessor<ChartTooltipBodyTarget<TDatum, TXValue, TYValue>>;
}) {
  const context: ChartTooltipBodyRenderContext<TDatum, TXValue, TYValue> = {
    get points() {
      return props.target().points;
    },
    get content() {
      return props.target().content;
    },
    defaultBody: <TanStackTooltipBody content={() => props.target().content} />,
    get pinned() {
      return props.target().pinned;
    },
    get dismiss() {
      return props.target().dismiss;
    },
  };

  return <Portal mount={props.target().element}>{props.render(context)}</Portal>;
}

const renderDefaultTooltipBody = <
  TDatum,
  TXValue extends ChartValue = ChartValue,
  TYValue extends ChartValue = ChartValue,
>(
  context: ChartTooltipBodyRenderContext<TDatum, TXValue, TYValue>,
) => <ModuixTooltipBody content={() => context.content} />;

function ChartPrimitive<
  TDatum,
  TXValue extends ChartValue = ChartValue,
  TYValue extends ChartValue = ChartValue,
>(props: ChartPlotProps<TDatum, TXValue, TYValue>) {
  const generatedId = `ts-chart-${createUniqueId().replaceAll(/[^a-zA-Z0-9_-]/g, '')}`;
  const resolvedRenderer = createMemo(
    () =>
      (props.renderer ??
        (props.motion === false ? svgChartRenderer : defaultChartRenderer)) as ChartRenderer<
        TDatum,
        TXValue,
        TYValue
      >,
  );
  const [tooltipTarget, setTooltipTarget] = createSignal<ChartTooltipBodyTarget<
    TDatum,
    TXValue,
    TYValue
  > | null>(null);

  const getOptions = () => {
    const {
      class: _class,
      motion: _motion,
      renderTooltipBody,
      renderer: _renderer,
      style: _style,
      ...others
    } = props;

    return {
      ...others,
      idPrefix: props.idPrefix ?? generatedId,
      renderer: resolvedRenderer(),
      onTooltipBodyChange: renderTooltipBody ? setTooltipTarget : undefined,
    };
  };

  const adapter = createChartRendererAdapter(getOptions());
  const initialMarkup = adapter.prerender();
  let surface!: HTMLDivElement;

  createEffect(() => adapter.update(getOptions()));
  onMount(() => adapter.mount(surface));
  onCleanup(() => adapter.destroy());

  return (
    <>
      <div
        class={clsx('ts-chart-host', props.class)}
        style={{
          position: 'relative',
          width: props.width === undefined ? '100%' : `${props.width}px`,
          height:
            props.height === undefined
              ? typeof props.aspectRatio === 'number' &&
                Number.isFinite(props.aspectRatio) &&
                props.aspectRatio > 0
                ? undefined
                : '320px'
              : `${props.height}px`,
          'aspect-ratio':
            props.height === undefined &&
            typeof props.aspectRatio === 'number' &&
            Number.isFinite(props.aspectRatio) &&
            props.aspectRatio > 0
              ? props.aspectRatio.toString()
              : undefined,
          ...props.style,
        }}
      >
        <div
          ref={(element) => (surface = element)}
          class="ts-chart-surface"
          style={{ width: '100%', height: '100%' }}
          innerHTML={initialMarkup}
        />
      </div>
      <Show when={props.renderTooltipBody} keyed>
        {(render) => (
          <Show when={tooltipTarget()} keyed>
            {(target) => <ChartTooltipBody render={render} target={() => target} />}
          </Show>
        )}
      </Show>
    </>
  );
}

function ChartPlot<
  TDatum,
  TXValue extends ChartValue = ChartValue,
  TYValue extends ChartValue = ChartValue,
>(props: ChartPlotProps<TDatum, TXValue, TYValue>) {
  const [local, others] = splitProps(props, [
    'class',
    'motion',
    'renderTooltipBody',
    'renderer',
    'style',
  ]);

  return (
    <ChartPrimitive
      {...others}
      class={clsx(styles.plot, local.class)}
      motion={local.motion}
      renderTooltipBody={local.renderTooltipBody ?? renderDefaultTooltipBody}
      renderer={local.renderer}
      style={local.style}
    />
  );
}

function ChartHeader(props: HTMLArkProps<'figcaption'>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <ark.figcaption
      asChild={local.asChild}
      {...others}
      data-scope="chart"
      data-part="header"
      data-slot="chart-header"
      class={clsx(styles.header, local.class)}
    />
  );
}

function ChartTitle(props: HTMLArkProps<'h3'>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <ark.h3
      asChild={local.asChild}
      {...others}
      data-scope="chart"
      data-part="title"
      data-slot="chart-title"
      class={clsx(styles.title, local.class)}
    />
  );
}

function ChartDescription(props: HTMLArkProps<'p'>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <ark.p
      asChild={local.asChild}
      {...others}
      data-scope="chart"
      data-part="description"
      data-slot="chart-description"
      class={clsx(styles.description, local.class)}
    />
  );
}

function ChartLegend(props: HTMLArkProps<'ul'>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <ark.ul
      asChild={local.asChild}
      {...others}
      data-scope="chart"
      data-part="legend"
      data-slot="chart-legend"
      class={clsx(styles.legend, local.class)}
    />
  );
}

function ChartLegendItem(props: HTMLArkProps<'li'> & { color?: string }) {
  const [local, others] = splitProps(props, ['asChild', 'class', 'color', 'style']);

  return (
    <ark.li
      asChild={local.asChild}
      {...others}
      data-scope="chart"
      data-part="legend-item"
      data-slot="chart-legend-item"
      class={clsx(styles.legendItem, local.class)}
      style={
        local.color
          ? ({
              '--moduix-chart-legend-indicator-color': local.color,
              ...(typeof local.style === 'object' && local.style ? local.style : {}),
            } as JSX.CSSProperties)
          : local.style
      }
    />
  );
}

const Chart = Object.assign(ChartRoot, {
  Root: ChartRoot,
  Plot: ChartPlot,
  Header: ChartHeader,
  Title: ChartTitle,
  Description: ChartDescription,
  Legend: ChartLegend,
  LegendItem: ChartLegendItem,
});

export { Chart };

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: grid;
    width: 100%;
    min-width: 0;
    gap: var(--moduix-chart-gap, var(--moduix-spacing-5));
    margin: 0;
    padding: var(--moduix-chart-padding, var(--moduix-spacing-5));
    border: var(--moduix-chart-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-chart-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-chart-radius, var(--moduix-radius-lg));
    background-color: var(--moduix-chart-bg, var(--moduix-color-card));
    box-shadow: var(--moduix-chart-shadow, var(--moduix-shadow-sm));
    color: var(--moduix-color-card-foreground);
  }

  .plot {
    min-width: 0;
    color: var(--moduix-chart-axis-color, var(--moduix-color-muted-foreground));

    --ts-chart-tooltip-background: var(--moduix-chart-tooltip-bg, var(--moduix-color-popover));
    --ts-chart-tooltip-border: var(
        --moduix-chart-tooltip-border-width,
        var(--moduix-border-width-sm)
      )
      solid var(--moduix-chart-tooltip-border-color, var(--moduix-color-border));
    --ts-chart-tooltip-border-radius: var(--moduix-chart-tooltip-radius, var(--moduix-radius-md));
    --ts-chart-tooltip-color: var(
      --moduix-chart-tooltip-color,
      var(--moduix-color-popover-foreground)
    );
    --ts-chart-tooltip-font: var(--moduix-weight-medium)
      var(--moduix-chart-tooltip-font-size, var(--moduix-text-xs)) /
      var(--moduix-chart-tooltip-line-height, var(--moduix-line-height-text-xs))
      var(--moduix-font-sans);
    --ts-chart-tooltip-padding: var(--moduix-chart-tooltip-padding, var(--moduix-spacing-3));
    --ts-chart-tooltip-shadow: var(--moduix-chart-tooltip-shadow, var(--moduix-shadow-lg));

    & :global(.ts-chart) {
      border-radius: var(--moduix-chart-plot-radius, var(--moduix-radius-md));
      outline: none;
    }

    & :global(.ts-chart:focus-visible) {
      outline: var(
          --moduix-chart-focus-ring-width,
          var(--moduix-focus-ring-width, var(--moduix-border-width-md))
        )
        solid var(--moduix-chart-focus-ring-color, var(--moduix-color-ring));
      outline-offset: var(--moduix-chart-focus-ring-offset, var(--moduix-focus-ring-offset));
    }
  }

  .header {
    display: grid;
    gap: var(--moduix-spacing-1);
  }

  .title {
    margin: 0;
    font-size: var(--moduix-text-lg);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--moduix-line-height-text-lg);
  }

  .description {
    margin: 0;
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
  }

  .legend {
    display: flex;
    flex-wrap: wrap;
    gap: var(--moduix-spacing-3);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .legendItem {
    display: inline-flex;
    align-items: center;
    gap: var(--moduix-spacing-2);
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);

    &::before {
      width: var(--moduix-spacing-2-5);
      height: var(--moduix-spacing-2-5);
      flex: none;
      border-radius: var(--moduix-radius-full);
      background-color: var(
        --moduix-chart-legend-indicator-color,
        var(--moduix-color-muted-foreground)
      );
      box-shadow: inset 0 0 0 var(--moduix-border-width-sm) rgb(0 0 0 / 8%);
      content: '';
    }
  }

  .defaultTooltipContent,
  .tooltipRows {
    display: grid;
    gap: var(--moduix-spacing-1);
  }

  .tooltipTitle {
    display: flex;
    align-items: center;
    gap: var(--moduix-spacing-2);
    color: var(--moduix-color-popover-foreground);
    font-weight: var(--moduix-weight-semibold);
  }

  .tooltipRow {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    column-gap: var(--moduix-spacing-2);

    &[data-has-swatch] {
      grid-template-columns: var(--moduix-spacing-2-5) minmax(0, 1fr) auto;
    }
  }

  .tooltipSwatch {
    width: var(--moduix-spacing-2-5);
    height: var(--moduix-spacing-2-5);
    border-radius: var(--moduix-radius-full);
    box-shadow: inset 0 0 0 var(--moduix-border-width-sm) rgb(0 0 0 / 8%);
  }

  .tooltipLabel {
    min-width: 0;
    color: var(--moduix-color-muted-foreground);
  }

  .tooltipValue {
    color: var(--moduix-color-popover-foreground);
    font-weight: var(--moduix-weight-semibold);
    font-variant-numeric: tabular-nums;
    text-align: right;
    white-space: nowrap;
  }
}
